<?php
namespace RDR\V2\HeadlessCMS\Portal;

use RDR\V2\HeadlessCMS\Meta;
use RDR\V2\HeadlessCMS\PostTypes;

if ( ! defined( 'ABSPATH' ) ) { exit; }

final class Articles extends ContentModule {
    public function list_page() {
        $search=isset($_GET['s'])?sanitize_text_field(wp_unslash($_GET['s'])):'';$paged=max(1,isset($_GET['paged'])?absint($_GET['paged']):1);
        $query=new \WP_Query(array('post_type'=>'post','post_status'=>array('publish','draft','pending','private'),'posts_per_page'=>20,'paged'=>$paged,'s'=>$search,'orderby'=>'modified','order'=>'DESC'));
        ob_start(); ?>
        <section class="rdr-card"><form method="get" action="<?php echo esc_url(Support::url('insights')); ?>" class="rdr-filters"><div class="rdr-field"><label for="rdr-article-search">Search</label><input id="rdr-article-search" name="s" value="<?php echo esc_attr($search); ?>" placeholder="Article title or content"></div><button class="rdr-button rdr-button-secondary" type="submit">Search</button></form></section>
        <section class="rdr-card rdr-table-card"><?php if($query->have_posts()):?><div class="rdr-table-wrap"><table class="rdr-table"><thead><tr><th>Article</th><th>Category</th><th>Featured</th><th>Publication</th><th>Published</th><th>Updated</th><th>Actions</th></tr></thead><tbody><?php foreach($query->posts as $post):$cats=wp_get_post_categories($post->ID,array('fields'=>'names'));?><tr><td><strong><?php echo esc_html($post->post_title?:'(Untitled)'); ?></strong><small>#<?php echo absint($post->ID); ?></small></td><td><?php echo esc_html($cats?implode(', ',$cats):'—'); ?></td><td><?php echo get_post_meta($post->ID,'_rdr_featured',true)?'Yes':'No'; ?></td><td><span class="rdr-badge"><?php echo esc_html(Support::portal_state_options()[Support::current_portal_state($post)]); ?></span></td><td><?php echo esc_html(Support::format_date($post->post_date)); ?></td><td><?php echo esc_html(Support::format_date($post->post_modified)); ?></td><td><a class="rdr-link" href="<?php echo esc_url(Support::url('insights/edit/'.$post->ID)); ?>">Edit</a></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="rdr-empty"><h2>No articles found</h2><p>Create an Insights article from the Portal.</p></div><?php endif;?></section>
        <?php $content=ob_get_clean();$actions='<a class="rdr-button rdr-button-primary" href="'.esc_url(Support::url('insights/add')).'">Add Article</a>';Shell::render('Insights','insights',$content,array('subtitle'=>'Manage native WordPress Posts through the custom Portal instead of Gutenberg for normal editing.','actions'=>$actions));
    }
    public function add_page(){ $this->form_page(null); }
    public function edit_page($id){$post=get_post(absint($id));if(!$post instanceof \WP_Post||'post'!==$post->post_type)Shell::simple_error(404,'Article not found','The requested Article does not exist or has the wrong content type.');if(!current_user_can('edit_post',$post->ID))Shell::simple_error(403,'Access denied','You do not have permission to edit this Article.');$this->form_page($post);}
    private function form_page($post){$is_edit=$post instanceof \WP_Post;$errors=array();$field_errors=array();$submitted=array();if('POST'===$_SERVER['REQUEST_METHOD']){$result=$this->handle_save($post);if(!empty($result['redirect'])){wp_safe_redirect($result['redirect']);exit;}$errors=$result['errors'];$field_errors=$result['field_errors'];$submitted=$result['submitted'];}$meta=$submitted&&isset($submitted['meta'])&&is_array($submitted['meta'])?$submitted['meta']:array();$title=$submitted?(isset($submitted['title'])?$submitted['title']:''):($is_edit?$post->post_title:'');$slug=$submitted?(isset($submitted['slug'])?$submitted['slug']:''):($is_edit?$post->post_name:'');$excerpt=$submitted?(isset($submitted['excerpt'])?$submitted['excerpt']:''):($is_edit?$post->post_excerpt:'');$content_value=$submitted?(isset($submitted['content'])?$submitted['content']:''):($is_edit?$post->post_content:'');$state=$submitted?(isset($submitted['portal_state'])?$submitted['portal_state']:'draft'):($is_edit?Support::current_portal_state($post):'draft');$date=$submitted?(isset($submitted['publish_date'])?$submitted['publish_date']:''):($is_edit?mysql2date('Y-m-d\TH:i',$post->post_date,false):current_time('Y-m-d\TH:i'));$selected_cat=$submitted?(isset($submitted['category'])?absint($submitted['category']):0):($is_edit?(int)(wp_get_post_categories($post->ID)[0]??0):0);$categories=get_categories(array('hide_empty'=>false));
        ob_start();?><?php echo $this->errors_html($errors); ?><form method="post" class="rdr-form rdr-editor-form" data-rdr-unsaved><?php wp_nonce_field('rdr_portal_article_save','rdr_portal_nonce'); ?>
        <section class="rdr-card"><h2>Article</h2><div class="rdr-form-grid"><?php echo $this->field('title','Title',$title,'text',true,'',isset($field_errors['title'])?$field_errors['title']:''); ?><?php echo $this->field('slug','Slug',$slug,'text',false,'Leave blank to generate from title.'); ?><div class="rdr-field"><label for="rdr-article-category">Category</label><select id="rdr-article-category" name="category"><option value="0">— None —</option><?php foreach($categories as $cat):?><option value="<?php echo absint($cat->term_id); ?>"<?php selected($selected_cat,$cat->term_id); ?>><?php echo esc_html($cat->name); ?></option><?php endforeach;?></select></div><?php echo $this->field('publish_date','Publish Date',$date,'datetime-local',false,'Used when the Article is published; draft safety still applies.'); ?><?php echo $this->select('portal_state','Publishing State',Support::portal_state_options(),$state); ?><?php echo $this->checkbox('meta[_rdr_featured]','Featured Article',$this->meta($post,'_rdr_featured',$meta)); ?></div><?php echo $this->textarea('excerpt','Excerpt',$excerpt,4); ?><?php echo Support::media_field('featured_image_id','Featured Image',$submitted?(isset($submitted['featured_image_id'])?$submitted['featured_image_id']:0):($is_edit?get_post_thumbnail_id($post->ID):0)); ?></section>
        <section class="rdr-card"><h2>Article Body</h2><p class="rdr-help">Controlled WordPress rich-text editor. Content is stored in native post_content and sanitized according to WordPress content capabilities.</p><div class="rdr-editor-wrap"><?php wp_editor($content_value,'rdr_portal_article_body',array('textarea_name'=>'content','media_buttons'=>true,'textarea_rows'=>18,'teeny'=>false,'quicktags'=>true)); ?></div></section>
        <section class="rdr-card"><h2>Relationships</h2><div class="rdr-form-grid"><div class="rdr-field"><label>Related Services</label><?php echo Support::post_multiselect('meta[_rdr_related_service_ids]',PostTypes::SERVICE,$this->meta($post,'_rdr_related_service_ids',$meta)); ?></div><div class="rdr-field"><label>Related Projects</label><?php echo Support::post_multiselect('meta[_rdr_related_project_ids]',PostTypes::PROJECT,$this->meta($post,'_rdr_related_project_ids',$meta)); ?></div></div></section>
        <section class="rdr-card"><h2>SEO</h2><div class="rdr-form-grid"><?php echo $this->field('meta[_rdr_seo_title]','SEO Title',$this->meta($post,'_rdr_seo_title',$meta)); ?><?php echo Support::media_field('meta[_rdr_og_image_id]','OG Image',$this->meta($post,'_rdr_og_image_id',$meta)); ?></div><?php echo $this->textarea('meta[_rdr_meta_description]','Meta Description',$this->meta($post,'_rdr_meta_description',$meta),4); ?></section>
        <div class="rdr-sticky-actions"><a class="rdr-button rdr-button-secondary" href="<?php echo esc_url(Support::url('insights')); ?>">Cancel</a><button class="rdr-button rdr-button-primary" type="submit" data-rdr-save><?php echo $is_edit?'Save Article':'Create Article'; ?></button><span class="rdr-save-state" data-rdr-save-state aria-live="polite"></span></div></form>
        <?php $content=ob_get_clean();Shell::render($is_edit?'Edit Article':'Add Article','insights',$content,array('breadcrumbs'=>array(array('label'=>'Insights','url'=>Support::url('insights')),array('label'=>$is_edit?'Edit':'Add'))));}
    private function handle_save($post){$is_edit=$post instanceof \WP_Post;$submitted=wp_unslash($_POST);$errors=array();$field_errors=array();if(!isset($_POST['rdr_portal_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['rdr_portal_nonce'])),'rdr_portal_article_save'))$errors[]='Security check failed. Reload and try again.';if($is_edit?!current_user_can('edit_post',$post->ID):!current_user_can('edit_posts'))$errors[]='You do not have permission to save this Article.';$title=isset($submitted['title'])?sanitize_text_field($submitted['title']):'';if(''===$title){$errors[]='Article title is required.';$field_errors['title']='Enter an Article title.';}$state=isset($submitted['portal_state'])?sanitize_key($submitted['portal_state']):'draft';if(!array_key_exists($state,Support::portal_state_options()))$errors[]='Publishing state is invalid.';$category=isset($submitted['category'])?absint($submitted['category']):0;if($category&&!term_exists($category,'category'))$errors[]='Article category is invalid.';$date=isset($submitted['publish_date'])?sanitize_text_field($submitted['publish_date']):'';$date_mysql='';if($date){$d=\DateTime::createFromFormat('Y-m-d\TH:i',$date);if(!$d||$d->format('Y-m-d\TH:i')!==$date)$errors[]='Publish date is invalid.';else $date_mysql=$d->format('Y-m-d H:i:s');}$meta=isset($submitted['meta'])&&is_array($submitted['meta'])?$submitted['meta']:array();$meta['_rdr_related_service_ids']=Support::validate_relation_ids(isset($meta['_rdr_related_service_ids'])?$meta['_rdr_related_service_ids']:array(),PostTypes::SERVICE);$meta['_rdr_related_project_ids']=Support::validate_relation_ids(isset($meta['_rdr_related_project_ids'])?$meta['_rdr_related_project_ids']:array(),PostTypes::PROJECT);if($errors)return array('errors'=>$errors,'field_errors'=>$field_errors,'submitted'=>$submitted);$mapped=Support::state_to_storage($state);$postarr=array('post_type'=>'post','post_title'=>$title,'post_name'=>isset($submitted['slug'])?sanitize_title($submitted['slug']):'','post_excerpt'=>isset($submitted['excerpt'])?sanitize_textarea_field($submitted['excerpt']):'','post_content'=>isset($submitted['content'])?wp_kses_post($submitted['content']):'','post_status'=>$mapped['post_status']);if($date_mysql)$postarr['post_date']=$date_mysql;if($is_edit){$postarr['ID']=$post->ID;$id=wp_update_post($postarr,true);}else{$id=wp_insert_post($postarr,true);}if(is_wp_error($id))return array('errors'=>array('WordPress could not save the Article: '.$id->get_error_message()),'field_errors'=>array(),'submitted'=>$submitted);if($category)wp_set_post_categories($id,array($category),false);else wp_set_post_categories($id,array(),false);$feature=isset($submitted['featured_image_id'])?absint($submitted['featured_image_id']):0;if($feature)set_post_thumbnail($id,$feature);else delete_post_thumbnail($id);$meta[Meta::PUBLICATION_STATE]=$mapped['rdr_state'];Support::save_meta_fields($id,Meta::article_fields(),$meta);return array('redirect'=>Support::url('insights/edit/'.$id).'?rdr_notice='.($is_edit?'saved':'created'));}
}
